text:
{
 "summary": {
  "es": "国会《こっかい》は、開《ひら》く期間《きかん》（会期《かいき》）を決《き》めて開《ひら》きます。毎年《まいとし》開《ひら》く常会《じょうかい》（会期《かいき》150日《にち》）と、臨時会《りんじかい》、特別会《とくべつかい》があります。会期《かいき》中《ちゅう》に決《き》まらなかった案《あん》は、原則《げんそく》として次《つぎ》の国会《こっかい》に引《ひ》きつがれません。",
  "hs": "国会は会期制（開く期間を決めて開くしくみ）をとっていて、常会（会期150日）・臨時会・特別会があります。会期中に議決されなかった案件は、原則として後の国会に引きつがれません。"
 },
 "blocks/0/text": {
  "es": "自分《じぶん》の仕事《しごと》に関係《かんけい》する法律《ほうりつ》の案《あん》が「会期《かいき》中《ちゅう》に成立《せいりつ》しなかった」とニュースで伝《つた》えられたら、その案《あん》はどうなる？",
  "hs": "自分の仕事に関係する法律案が「会期中に成立しなかった」と報道されたら、その法律案はどうなる？"
 },
 "blocks/3/text": {
  "es": "衆議院《しゅうぎいん》によると、国会《こっかい》を開《ひら》くために議員《ぎいん》を集《あつ》めること（召集《しょうしゅう》）は、内閣《ないかく》が決《き》めます。そして、天皇《てんのう》が出《だ》す召集《しょうしゅう》の文書《ぶんしょ》（召集詔書《しょうしゅうしょうしょ》）を、広《ひろ》く知《し》らせることで行《おこな》われます（憲法《けんぽう》第《だい》7条《じょう》第《だい》2号《ごう》）。",
  "hs": "衆議院によると、国会の召集《しょうしゅう》（国会を開くために議員を集めること）は内閣が決定し、召集詔書《しょうしゅうしょうしょ》の公布（広く知らせること）によって行われます（憲法第7条第2号）。"
 },
 "blocks/5/text": {
  "es": "会期《かいき》中《ちゅう》に決《き》まらなかった案《あん》は、次《つぎ》の国会《こっかい》に引《ひ》きつがれません（国会《こっかい》法《ほう》第《だい》68条《じょう》、会期《かいき》不《ふ》継続《けいぞく》の原則《げんそく》）。ただし、国会《こっかい》が閉《と》じている間《あいだ》も委員会《いいんかい》で話《はな》し合《あ》うと議院《ぎいん》が決《き》めた案《あん》は、次《つぎ》の国会《こっかい》に引《ひ》きつがれます。",
  "hs": "会期中に議決されなかった案件は、後の国会に引きつがれません（国会法第68条、会期不｜継続《けいぞく》の原則）。ただし、委員会で閉会中｜審査《しんさ》（国会が閉じている間の審査《しんさ》）を行うと議院が議決した案件は、後の国会に引きつがれます。"
 },
 "blocks/6/text": {
  "es": "衆議院《しゅうぎいん》が解散《かいさん》されると、参議院《さんぎいん》も同時《どうじ》に閉《と》じます。解散《かいさん》の日《ひ》から40日《にち》以内《いない》に総選挙《そうせんきょ》を行《おこな》い、選挙《せんきょ》の日《ひ》から30日《にち》以内《いない》に特別会《とくべつかい》が開《ひら》かれます（第《だい》54条《じょう》）。",
  "hs": "衆議院が解散されると、参議院も同時に閉会になります。解散の日から40日以内に総選挙、選挙の日から30日以内に特別会が召集《しょうしゅう》されます（第54条）。"
 }
}
